// Flatten Breeze form entries and auto-detect the notes / free-text field.
//
// Inputs:
//   - $('List Form Fields')  -> field definitions for the form
//   - $input (this node)     -> the raw entries from "List Form Entries"
//
// Breeze returns bare JSON arrays. Depending on n8n settings the array may
// arrive as one item (json = array) or split into one item per element, so
// we normalise both shapes here.

const FREE_TEXT_TYPES = ['single_line', 'multiple_lines', 'textarea', 'paragraph'];
const NOTES_NAME_RE = /note|comment|message|prayer|question|request|detail/i;

function asArray(value) {
  if (Array.isArray(value)) return value;
  if (value && Array.isArray(value.data)) return value.data;
  if (value && typeof value === 'object') return [value];
  return [];
}

function flattenValue(v) {
  if (v === null || v === undefined) return '';
  if (typeof v === 'object') {
    // Breeze sometimes returns structured values (e.g. name -> {first,last}).
    if ('value' in v) return v.value;
    return Object.values(v).filter(Boolean).join(' ').trim();
  }
  return v;
}

// ---- 1. Resolve field definitions ----------------------------------------
let fieldList = [];
try {
  fieldList = asArray($('List Form Fields').first().json);
} catch (e) {
  // node may have a different name if renamed; fail loud and clear
  throw new Error('Could not read "List Form Fields" output: ' + e.message);
}

const idToName = {};
for (const f of fieldList) {
  if (f && f.id !== undefined) idToName[String(f.id)] = f.name || ('field_' + f.id);
}

// Prefer a field whose NAME looks like a notes box; fall back to first
// free-text field type.
let notesField =
  fieldList.find((f) => f && NOTES_NAME_RE.test(f.name || '')) ||
  fieldList.find((f) => f && FREE_TEXT_TYPES.includes(f.type)) ||
  null;
const notesFieldId = notesField ? String(notesField.id) : null;

// ---- 2. Flatten entries ---------------------------------------------------
const out = [];
for (const item of $input.all()) {
  for (const entry of asArray(item.json)) {
    const resp = entry.response || entry.details || entry.fields || {};
    const row = {
      entry_id: entry.id ?? null,
      created_on: entry.created_on ?? entry.created ?? null,
      person_id: entry.person_id ?? null,
      notes_field_id: notesFieldId,
      notes: notesFieldId ? flattenValue(resp[notesFieldId]) : null,
    };
    // Also expose every answered field by its human-readable name.
    for (const [fid, val] of Object.entries(resp)) {
      const key = idToName[fid] || ('field_' + fid);
      row[key] = flattenValue(val);
    }
    out.push({ json: row });
  }
}

return out;
